}

{
  "definition": {
    "status": "grounded",
    "text": "Entropy measures the impurity of class distributions at a decision tree node, calculated as -sum_y P(y|v) * log P(y|v). It is maximized when all classes are equally likely.",
    "supporting_evidence_labels": ["E1", "E5"],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "text": "Entropy quantifies the uncertainty in class distribution at a node, with zero entropy indicating perfect purity (one class dominates) and maximum entropy indicating equal class distribution.",
    "supporting_evidence_labels": ["E4", "E5"],
    "abstention_reason": ""
  }
}

